import{_ as a,o as r,c as t,a2 as i}from"./chunks/framework.CqGPl1zp.js";const u=JSON.parse('{"title":"【v2026-07】","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/2026-07.md","filePath":"changelog/2026-07.md","lastUpdated":null}'),o={name:"changelog/2026-07.md"};function n(l,e,c,d,f,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="【v2026-07】" tabindex="-1">【v2026-07】 <a class="header-anchor" href="#【v2026-07】" aria-label="Permalink to &quot;【v2026-07】&quot;">​</a></h1><h2 id="管理后台移动端完成全模块适配-增强工作流与-crm-数据统计" tabindex="-1">管理后台移动端完成全模块适配，增强工作流与 CRM 数据统计 <a class="header-anchor" href="#管理后台移动端完成全模块适配-增强工作流与-crm-数据统计" aria-label="Permalink to &quot;管理后台移动端完成全模块适配，增强工作流与 CRM 数据统计&quot;">​</a></h2><p>本月概要：</p><ul><li>【移动端】完成 Mall 商城、ERP、CRM、AI 大模型、IoT 物联网、MES、WMS、IM 即时通讯、公众号、支付、会员等业务模块迁移，实现全部功能对齐。</li><li>【移动端】新增钉钉、企业微信、微信公众号 OAuth 登录及微信小程序快捷登录，支持三方账号绑定。</li><li>【代码生成器】完善 Vue3 Admin UniApp 代码生成，支持单表、树表及三种主子表模式。</li><li>【工作流】新增流程评论能力，并支持流程模型 JSON 导入、导出。</li><li>【CRM】补齐客户、公海、销售漏斗、商机转化率、员工业绩、产品销售等数据统计，并新增部门、员工销售与回款目标管理。</li><li>【后端框架】链路追踪从 OpenTracing 迁移至 OpenTelemetry。</li></ul><h3 id="📈-statistic" tabindex="-1">📈 Statistic <a class="header-anchor" href="#📈-statistic" aria-label="Permalink to &quot;📈 Statistic&quot;">​</a></h3><ul><li>总代码行数：442190</li><li>源码代码行数：277438</li><li>注释行数：98821</li><li>单元测试用例数：2428</li></ul><h3 id="🚀-新增功能" tabindex="-1">🚀 新增功能 <a class="header-anchor" href="#🚀-新增功能" aria-label="Permalink to &quot;🚀 新增功能&quot;">​</a></h3><p>管理后台移动端：</p><ul><li>【新增】UniApp 管理后台完成全部业务模块的移动端迁移：在原有 System、Infra、BPM 模块基础上，新增覆盖 Mall 商城、ERP、CRM、AI 大模型、IoT 物联网、MES、WMS、IM 即时通讯、公众号、支付、会员等模块，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 、<a href="https://gitee.com/latepush" target="_blank" rel="noreferrer">@Bob</a> 贡献</li><li>【新增】代码生成器完善 Vue3 Admin UniApp + Wot UI 代码生成，支持单表、树表，以及标准、内嵌、ERP 三种主子表模式，补齐 API、列表、搜索、表单、详情和字段控件，并增加类名、属性名及输出路径碰撞校验和生成快照测试，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 贡献 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/commit/2ef66566d4befc054a5657c475866e78702f0bea" target="_blank" rel="noreferrer">2ef66566</a> 、<a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/commit/0cb951f3344107f01a3c7168a24dd49493bc0914" target="_blank" rel="noreferrer">0cb951f3</a></li><li>【新增】UniApp 移动端支持三方登录与账号绑定，H5 支持钉钉、企业微信、微信公众号 OAuth 登录，微信小程序支持快捷登录，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 贡献 <a href="https://gitee.com/yudaocode/yudao-ui-admin-uniapp/commit/ffb374a80d683f6f8ed2d105ee8877df1bcf629f" target="_blank" rel="noreferrer">ffb374a8</a></li></ul><p>工作流专区：</p><ul><li>【新增】流程详情新增「流程评论」页签和「评论」操作，复用 Flowable Comment 能力，支持按流程实例查看审批评论、普通评论及其对应任务、评论人、评论类型，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 贡献</li><li>【新增】流程模型支持导入、导出 JSON，完整保留 BPMN XML 或简易设计器模型配置，并同步适配 Vue3、Vben5 的 Ant Design Vue、Element Plus 和 antdv-next 版本，由 <a href="https://gitee.com/nnzb" target="_blank" rel="noreferrer">@nnzb</a> 贡献 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/pulls/1572" target="_blank" rel="noreferrer">后端 #1572</a> 、<a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/pulls/381" target="_blank" rel="noreferrer">Vben5 #381</a></li></ul><p>CRM 客户管理专区：</p><ul><li>【新增】CRM 数据统计补齐客户分析、公海客户分析、销售漏斗分析、商机转化率分析、员工业绩合同汇总、产品销售情况统计、产品分类销售分析和业绩达成统计，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 贡献</li><li>【新增】CRM 业绩目标设置，支持按部门、员工配置销售目标和回款目标，并在业绩达成中按月查看目标金额、完成金额和完成率，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 贡献</li></ul><p>后端框架专区：</p><ul><li>【新增】Excel 数据字典转换器新增多值转换器 <code>MultiDictConvert</code>，由 <a href="https://github.com/1139195538" target="_blank" rel="noreferrer">@1139195538</a> 贡献 <a href="https://github.com/YunaiV/ruoyi-vue-pro/pull/1162" target="_blank" rel="noreferrer">#1162</a></li><li>【升级】微服务版链路追踪从 OpenTracing 迁移到 OpenTelemetry，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 贡献 <a href="https://gitee.com/zhijiantianya/yudao-cloud/pulls/210" target="_blank" rel="noreferrer">#210</a> 、<a href="https://gitee.com/zhijiantianya/yudao-cloud/pulls/232" target="_blank" rel="noreferrer">#232</a></li></ul><h3 id="🐞-问题修复" tabindex="-1">🐞 问题修复 <a class="header-anchor" href="#🐞-问题修复" aria-label="Permalink to &quot;🐞 问题修复&quot;">​</a></h3><p>管理后台移动端：</p><ul><li>【修复】UniApp 移动端正式环境登录成功后，业务接口持续返回 401 时会反复调用 <code>refresh-token</code> 的问题；刷新令牌后重放请求若仍 401，将统一进入登录失效处理，避免无限刷新循环，并兼容无 <code>refreshToken</code>、刷新请求自身失效等边界场景，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-uniapp/commit/3c129999eeea7ffaadc62cfd32e2919f57434543" target="_blank" rel="noreferrer">3c129999</a> ，对应 <a href="https://t.zsxq.com/UHHUR" target="_blank" rel="noreferrer">https://t.zsxq.com/UHHUR</a></li></ul><p>管理后台专区：</p><ul><li>【修复】Vben5.0 管理后台通用确认弹窗按钮事件未正确透传的问题，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/1cab0e4e81ac5f701aa7d140109f623882996c1d" target="_blank" rel="noreferrer">1cab0e4e</a> ，对应 <a href="https://t.zsxq.com/rRbZJ" target="_blank" rel="noreferrer">https://t.zsxq.com/rRbZJ</a></li><li>【修复】Vben5.0 管理后台租户套餐和角色菜单授权取消部分子菜单后，半选父菜单未随权限提交，导致新租户管理员菜单被过滤的问题；回显时还原完整选中节点、提交时补齐祖先菜单，并修复 Tree 级联选择产生重复节点的问题，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/b5029a0b674026f9b1d121fe590e084a8a18e321" target="_blank" rel="noreferrer">b5029a0b</a> ，对应 <a href="https://t.zsxq.com/vfS9w" target="_blank" rel="noreferrer">https://t.zsxq.com/vfS9w</a></li><li>【修复】WMS 入库、出库、移库、盘库单打印时，条码偶发空白或复用上一张条码的问题；打印前先卸载旧条码 DOM，加载新单据后等待 CODE39 条码重建和绘制完成再触发打印，，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3/commit/e4c57dc8589e68ea5e999fe1268bb70053479134" target="_blank" rel="noreferrer">e4c57dc8</a> 、<a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/9f990e0ab375fe826ba4d7ce27258426547532b5" target="_blank" rel="noreferrer">9f990e0a</a> ，对应 <a href="https://t.zsxq.com/kpzqv" target="_blank" rel="noreferrer">https://t.zsxq.com/kpzqv</a></li><li>【修复】Vue3 管理后台日期范围快捷项未按自然日边界提交，导致“今年”等范围出现 08:00:00 或点击时刻的问题；统一今天、昨天、最近 7 天、最近 30 天、本月和今年的起止时间为 00:00:00 至 23:59:59，并修复每月 1 日“本月”范围逆序的问题，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3/commit/4193bdc820dc97f23ee4f35e962b60045c99d5e3" target="_blank" rel="noreferrer">4193bdc8</a> ，对应 <a href="https://t.zsxq.com/IdY6a" target="_blank" rel="noreferrer">https://t.zsxq.com/IdY6a</a></li></ul><p>商城系统专区：</p><ul><li>【修复】商城 App 微信支付错误使用小程序参数格式，导致无法调起微信支付的问题；改为按 App 规范通过全小写 <code>orderInfo</code> 传递支付参数，并兼容后端微信支付 V2、V3 返回字段的命名差异，由 <a href="https://gitee.com/code-liangcheng" target="_blank" rel="noreferrer">@Alex Chen</a> 贡献 <a href="https://gitee.com/yudaocode/yudao-mall-uniapp/pulls/182" target="_blank" rel="noreferrer">#182</a> 、<a href="https://gitee.com/yudaocode/yudao-mall-uniapp/commit/2c999f5f2fd6ded9b56fd4515ae4f4d3a9f4afbd" target="_blank" rel="noreferrer">2c999f5f</a></li><li>【修复】Vben5.0 管理后台商城商品 SKU 修改时，详情回填会误触发规格 / 分销类型变更并重置 SKU，导致销售价、市场价、成本价、库存、重量、体积及一二级返佣回显为 0 的问题，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/396ba7dcfd3c6fca4bc6cab39cdf54039575c0dc" target="_blank" rel="noreferrer">396ba7dc</a> ，对应 <a href="https://t.zsxq.com/atpYj" target="_blank" rel="noreferrer">https://t.zsxq.com/atpYj</a></li></ul><p>工作流专区：</p><ul><li>【修复】UniApp 移动端 BPM 动态表单日期范围字段只显示单个日期的问题；范围型 <code>DatePicker</code>（如 <code>daterange</code>、<code>datetimerange</code>）现在会按数组值初始化并使用日历范围选择组件，避免流程表单移动端无法正确选择日期区间，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-uniapp/commit/f2113a95cb3834cab2af9e2b4d003bbd9dc23226" target="_blank" rel="noreferrer">f2113a95</a> ，对应 <a href="https://t.zsxq.com/Ct64E" target="_blank" rel="noreferrer">https://t.zsxq.com/Ct64E</a></li><li>【修复】UniApp 移动端 BPM 动态表单未执行字段 <code>blur</code>、<code>focus</code> 事件，以及事件脚本请求后端接口时未自动携带登录态的问题；补齐 <code>$FNX</code>、<code>$inject</code> 事件解析和普通字段、子表字段事件转发，<code>api.fetch</code> 统一复用项目 HTTP 请求并自动携带 Token、租户信息，同时兼容微信小程序脚本执行和子表异步回填场景，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/yudaocode/yudao-ui-admin-uniapp/commit/8fb40d5d2207547c3cc2a1274290eb806dabfcf5" target="_blank" rel="noreferrer">8fb40d5d</a></li><li>【修复】BPM 流程表单部门选择组件在表单设计器中会将当前登录用户部门保存为固定默认值的问题，设计器内不再自动写入当前部门，避免流程表单发布后默认部门不再跟随实际登录用户变化，由 <a href="https://gitee.com/jason-zhou" target="_blank" rel="noreferrer">@Jason</a> 贡献 <a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3/pulls/889" target="_blank" rel="noreferrer">Vue3 #889</a> 、<a href="https://gitee.com/yudaocode/yudao-ui-admin-vue3/commit/a4d14bbb247b062b385edb06d3f7ad580db1d94f" target="_blank" rel="noreferrer">a4d14bbb</a> 、<a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/pulls/379" target="_blank" rel="noreferrer">Vben5 #379</a> 、<a href="https://gitee.com/yudaocode/yudao-ui-admin-vben/commit/42b5d8943b543228b4fffa2ef20365e0f375010d" target="_blank" rel="noreferrer">42b5d894</a></li></ul><p>后端框架专区：</p><ul><li>【修复】微服务网关异常日志默认无法看到 SkyWalking TraceId 的问题，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 贡献</li><li>【修复】管理端和会员端短信、三方及微信小程序等登录方式未统一校验账号禁用状态，导致禁用用户仍可获取 Token 的问题；统一在创建 Token 前校验账号状态，并在禁用会员时撤销其 Token，同时保留三方账号绑定关系，由 <a href="https://gitee.com/zhijiantianya" target="_blank" rel="noreferrer">@芋道源码</a> 修复 <a href="https://gitee.com/zhijiantianya/ruoyi-vue-pro/commit/f639a76b43" target="_blank" rel="noreferrer">f639a76b</a> ，对应 <a href="https://wx.zsxq.com/group/88858522214142/topic/22255482581881881" target="_blank" rel="noreferrer">https://wx.zsxq.com/group/88858522214142/topic/22255482581881881</a></li></ul><h3 id="🔨-dependency-upgrades" tabindex="-1">🔨 Dependency Upgrades <a class="header-anchor" href="#🔨-dependency-upgrades" aria-label="Permalink to &quot;🔨 Dependency Upgrades&quot;">​</a></h3><p>所有分支：</p><ul><li>【升级】fastjson2 from 2.0.62 to 2.0.63</li><li>【移除】剔除 EasyTrans、RocketMQ、JustAuth、支付宝 SDK、JimuReport、JimuBI、TinyFlow 等三方依赖传递引入的 fastjson1，统一使用 fastjson2 官方 1.x API 兼容模块</li></ul><p>微服务版：</p><ul><li>【新增】引入 <code>opentelemetry-api</code>、<code>opentelemetry-sdk</code>、<code>opentelemetry-exporter-otlp</code>，替换原 OpenTracing 相关依赖</li><li>【升级】JDK8 分支 <code>skywalking.version</code> from 8.12.0 to 9.6.0，与 JDK17 分支保持一致</li></ul>',31)])])}const s=a(o,[["render",n]]);export{u as __pageData,s as default};
